<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useUserInfoStore} from '@/stores/userInfo'
import {notificationList,notificationDetail,notificationWrite,type Notification,type NotificationDetail,type NotificationWrite,type DispatchMode} from '@/api/notifications'
const user=useUserInfoStore(),rows=ref<Notification[]>([]),page=ref(1),total=ref(0),status=ref(''),orderId=ref(''),detail=ref<NotificationDetail>(),selected=ref('')
const loading=ref(false),sending=ref(false),ready=ref(false),error=ref(''),message=ref(''),note=ref(''),mode=ref<DispatchMode>('SUCCESS'),stale=ref(false)
const pending=ref<{id:string;action:'mock-dispatch'|'retry';body:NotificationWrite}>()
const frozen=computed(()=>loading.value||sending.value||!!pending.value)
const has=(code:string)=>user.permissions.some(p=>p.code===code)
const dispatchAllowed=computed(()=>has('notifications.dispatch.mock')),retryAllowed=computed(()=>has('notifications.retry'))
const labels:Record<string,string>={PENDING:'等待派送',RETRY:'等待重試',SENT:'mock 已接受',DEAD:'重試已用盡'}
const kinds:Record<string,string>={PREORDER_ALLOCATED:'預購到貨分配',PREORDER_SHIPPED:'預購出貨',PREORDER_DELIVERED:'預購送達',PREORDER_PAYMENT_SUCCEEDED:'預購付款成功',PREORDER_PAYMENT_FAILED:'預購付款失敗',PREORDER_PAYMENT_REVIEW_REQUIRED:'預購付款待核對',PREORDER_REFUNDED:'預購退款',PREORDER_REVIEW_REFUNDED:'預購核對退款',PREORDER_PLACED:'預購下單',PREORDER_CANCELLED:'預購取消',PREORDER_EXPIRED:'預購逾時',ORDER_PLACED:'下單',ORDER_CANCELLED:'取消',ORDER_EXPIRED:'逾時',PAYMENT_SUCCEEDED:'付款成功',PAYMENT_FAILED:'付款失敗',PAYMENT_REVIEW_REQUIRED:'付款待核對',ORDER_SHIPPED:'出貨',ORDER_DELIVERED:'送達',ORDER_REFUNDED:'訂單退款',REVIEW_REFUNDED:'異常付款退款',RETURN_REQUESTED:'退貨申請',RETURN_RECEIVED:'退貨驗收',RETURN_REJECTED:'退貨拒絕'}
function failure(e:any){return e.response?.data?.message||e.message||'暫時無法連線。'}
async function load(){if(sending.value)return;loading.value=true;ready.value=false;error.value='';try{const r=await notificationList(page.value,status.value,orderId.value.trim());rows.value=r.items;total.value=r.total;if(selected.value)detail.value=await notificationDetail(selected.value);ready.value=true}catch(e){error.value=failure(e)}finally{loading.value=false}}
async function select(id:string){if(frozen.value||!ready.value||!has('notifications.detail'))return;loading.value=true;ready.value=false;error.value='';try{const r=await notificationDetail(id);selected.value=id;detail.value=r;note.value='';mode.value='SUCCESS';stale.value=false;ready.value=true}catch(e){error.value=failure(e)}finally{loading.value=false}}
async function filter(){if(frozen.value)return;selected.value='';detail.value=undefined;page.value=1;await load()}
async function send(action:'mock-dispatch'|'retry'){if(sending.value)return;if(!pending.value){const d=detail.value;if(!ready.value||stale.value||!d||!note.value.trim()||(action==='mock-dispatch'?!(dispatchAllowed.value&&d.message.canDispatch):!(retryAllowed.value&&d.message.canRetry)))return;pending.value={id:d.message.id,action,body:{requestId:crypto.randomUUID(),expectedVersion:d.message.version,note:note.value.trim(),...(action==='mock-dispatch'?{mode:mode.value}:{})}}}sending.value=true;error.value='';try{const p=pending.value;const r=await notificationWrite(p.id,p.action,p.body);pending.value=undefined;note.value='';message.value=r.replayed?'原操作已核對，沒有重複處理。':`操作已記錄：${labels[r.current.status]||r.current.status}。`;sending.value=false;await load()}catch(e:any){const code=e.response?.status;if(code&&code>=400&&code<500){pending.value=undefined;stale.value=code===409;if(stale.value)ready.value=false;error.value=failure(e)+(stale.value?'；保留未送原因，請重讀後重新開啟詳情。':'')}else error.value='結果尚未確認。請重試同一操作，表單暫時凍結。'}finally{sending.value=false}}
function pretty(value:string){try{return JSON.stringify(JSON.parse(value),null,2)}catch{return value}}
onMounted(load)
</script>
<template>
<section class="notifications-panel card"><div class="card-body"><h1>訂單通知</h1><p>通知隨訂單交易保存。此處使用免費本地 MOCK，沒有寄送 Email、簡訊或推播給真人；mock 接受不代表實際送達。</p><p>失敗最多嘗試五次，之後需人工重新排程。時間為 Asia/Taipei。</p>
<form @submit.prevent="filter"><fieldset :disabled="frozen"><label>通知狀態<select v-model="status" aria-label="通知狀態"><option value="">全部狀態</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><label>訂單 ID<input v-model="orderId" placeholder="完整訂單 UUID" maxlength="36"></label><button type="submit">篩選通知</button></fieldset></form>
<p role="alert" v-if="error">{{error}}</p><p role="status" v-if="message">{{message}}</p><p v-if="loading">載入中…</p><button :disabled="loading||sending" @click="load">重讀資料</button><p v-if="!dispatchAllowed&&!retryAllowed">目前為唯讀，不能派送或重新排程。</p>
<div class="table-wrap"><table><thead><tr><th>事件／訂單</th><th>狀態</th><th>嘗試／版本</th><th>操作</th></tr></thead><tbody><tr v-for="n in rows" :key="n.id"><td>{{kinds[n.eventKind]||n.eventKind}}<br><small>{{n.orderId}}</small></td><td>{{labels[n.status]||n.status}}</td><td>{{n.attempts}}／{{n.version}}</td><td><button v-if="has('notifications.detail')" :disabled="frozen||!ready" @click="select(n.id)">詳情 {{n.id}}</button></td></tr></tbody></table><p v-if="ready&&!rows.length">沒有符合條件的通知。</p></div>
<div class="actions"><button :disabled="page===1||frozen" @click="page--;load()">上一頁</button><span>第 {{page}} 頁 · 共 {{total}} 筆</span><button :disabled="page*20>=total||frozen" @click="page++;load()">下一頁</button></div>
<section v-if="detail" class="detail"><h2>通知詳情</h2><p>{{detail.message.id}} · {{labels[detail.message.status]}} · 版本 {{detail.message.version}}</p><p>累計嘗試 {{detail.message.attempts}}；本輪 {{detail.message.cycleAttempts}}／5；下次 {{detail.message.nextAttemptAt||'—'}}；錯誤 {{detail.message.lastError||'—'}}。</p><p>Mock provider 已接受：{{detail.message.mockAccepted?'是':'否'}}；佇列確認時間 {{detail.message.sentAt||'—'}}。</p><h3>原始事件快照</h3><pre>{{pretty(detail.snapshot)}}</pre>
<form v-if="dispatchAllowed||retryAllowed" @submit.prevent="send('mock-dispatch')"><fieldset :disabled="frozen||stale||!ready"><label>操作原因<textarea v-model="note" required maxlength="500" /></label><label v-if="dispatchAllowed">Mock 派送情境<select v-model="mode" aria-label="Mock 派送情境"><option value="SUCCESS">成功接受</option><option value="FAIL_BEFORE">接受前失敗</option><option value="FAIL_AFTER_ACCEPT">已接受但結果遺失</option></select></label></fieldset><div class="actions"><button v-if="pending" type="button" :disabled="sending" @click="send(pending.action)">重試同一操作</button><template v-else><button v-if="dispatchAllowed" type="submit" :disabled="frozen||stale||!ready||!detail.message.canDispatch||!note.trim()">模擬派送</button><button v-if="retryAllowed" type="button" :disabled="frozen||stale||!ready||!detail.message.canRetry||!note.trim()" @click="send('retry')">重新排程</button></template></div><p v-if="pending">待核對操作：{{pending.body.requestId}}。保留原 UUID 與內容重試；重整後先核對紀錄。</p><p v-if="!detail.mockEnabled">Mock 派送未啟用，通知仍會保存。</p></form>
<h3>唯讀操作紀錄</h3><details v-for="e in detail.events" :key="e.requestId"><summary>{{e.createdAt}} · {{e.action}} · {{e.result}} · {{e.actorUsername}}</summary><p>{{e.requestId}} · {{e.beforeStatus}} → {{e.afterStatus}} · 版本 {{e.afterVersion}} · 嘗試 {{e.attemptNumber}}</p><p>原因：{{e.note}}</p></details><p v-if="!detail.events.length">尚無派送或重排紀錄。</p></section></div></section>
</template>
<style scoped>
.notifications-panel{min-width:0;max-width:1400px}.notifications-panel h1{font-size:1.5rem}h2{font-size:1.2rem}h3{font-size:1rem}.notifications-panel p,td,pre,small{overflow-wrap:anywhere}.actions{display:flex;gap:.7rem;flex-wrap:wrap;margin:1rem 0;align-items:center}button{padding:.5rem .7rem;border:1px solid #1b1f3b;border-radius:5px;background:white;color:#1b1f3b;max-width:100%;overflow-wrap:anywhere}button:disabled{opacity:.5}label{display:block;margin:.7rem 0}input,textarea,select{display:block;width:100%;max-width:32rem;padding:.5rem}fieldset{min-width:0}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid #e3e5ec;padding:.7rem}.detail{border:1px solid #d5d8e1;padding:1rem;margin-top:1rem}details{padding:.7rem;border-bottom:1px solid #e3e5ec}pre{white-space:pre-wrap}[role=alert]{color:#8a1c1c}
</style>
